begin;
create function pg_temp.assert_true(v boolean,m text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'assertion failed: %',m; end if; end$$;
create function pg_temp.error(q text,s text) returns void language plpgsql as $$declare got text; begin begin execute q; exception when others then got:=sqlstate; end; if got is distinct from s then raise exception 'expected %, got % for %',s,got,q; end if; end$$;
do $$declare target uuid:=gen_random_uuid(); reporter uuid:=gen_random_uuid(); admin uuid:=gen_random_uuid(); third uuid:=gen_random_uuid(); post uuid; parent uuid; ticket uuid; r jsonb; d text; duration interval; rid uuid;
begin
 insert into auth.users(id) values(target),(reporter),(admin),(third);
 insert into public.user_roles(user_id,role) values(admin,'admin');
 insert into storage.objects(bucket_id,name) values('community-posts',target||'/existing.webp');
 insert into public.community_posts(author_id,image_path) values(third,third||'/third.webp') returning id into post;
 insert into public.community_comments(post_id,author_id,body) values(post,target,'parent') returning id into parent;
 perform set_config('request.jwt.claim.sub',reporter::text,true); set local role authenticated;
 perform public.community_block_user(target);
 perform pg_temp.error(format('insert into public.community_comments(post_id,author_id,body,parent_comment_id) values(%L,auth.uid(),''reply'',%L)',post,parent),'42501');
 perform public.community_unblock_user(target);
 ticket:=public.community_report_content('comment',post,parent,'spam',null);
 perform pg_temp.error(format('select public.ops_community_restrict_user(%L,''24h'',''spam'','''')',target),'42501');
 perform set_config('request.jwt.claim.sub',admin::text,true);
 perform pg_temp.error(format('select public.ops_community_restrict_user(%L,''24h'',''spam'','''')',admin),'42501');
 perform pg_temp.error(format('select public.ops_community_restrict_user(%L,''24h'',''spam'','''',%L)',reporter,ticket),'22023');
 foreach d in array array['24h','3d','7d','30d','permanent'] loop
  r:=public.ops_community_restrict_user(target,d,'spam','test',ticket);
  duration:=case d when '24h' then interval '24 hours' when '3d' then interval '3 days' when '7d' then interval '7 days' when '30d' then interval '30 days' end;
  perform pg_temp.assert_true(case when d='permanent' then r->>'ends_at' is null else (r->>'ends_at')::timestamptz-(r->>'starts_at')::timestamptz=duration end,'moderation duration '||d);
 end loop;
 rid:=(r->>'id')::uuid;
 perform set_config('test.third',third::text,true); perform set_config('test.target',target::text,true); perform set_config('test.reporter',reporter::text,true); perform set_config('test.admin',admin::text,true); perform set_config('test.post',post::text,true); perform set_config('test.parent',parent::text,true); perform set_config('test.ticket',ticket::text,true); perform set_config('test.rid',rid::text,true);
 reset role;
end$$;
do $$declare target uuid:=current_setting('test.target')::uuid; reporter uuid:=current_setting('test.reporter')::uuid; admin uuid:=current_setting('test.admin')::uuid; post uuid:=current_setting('test.post')::uuid; parent uuid:=current_setting('test.parent')::uuid; ticket uuid:=current_setting('test.ticket')::uuid; rid uuid:=current_setting('test.rid')::uuid; r jsonb; workout jsonb; support_id uuid;
begin
 set local role authenticated;
 r:=public.ops_community_restriction_status(target);
 perform pg_temp.assert_true(jsonb_array_length(r->'history')=5,'replacement retains five history entries');
 perform pg_temp.assert_true((select count(*)=4 from jsonb_array_elements(r->'history') x where x->>'status'='revoked'),'replacement revokes previous active restrictions');
 perform set_config('request.jwt.claim.sub',reporter::text,true);
 perform pg_temp.assert_true(public.community_access_allowed(),'reporter remains unrestricted');
 perform public.community_acknowledge_restriction(rid);
 perform pg_temp.error(format('select public.community_send_message(%L,''incoming'',gen_random_uuid())',target),'42501');
 perform set_config('request.jwt.claim.sub',target::text,true);
 r:=public.community_access_status();
 perform pg_temp.assert_true(r->'active'->>'acknowledged_at' is null,'peer cannot acknowledge restriction');
 perform pg_temp.assert_true(not (r->'active' ? 'source_ticket_id') and not (r->'active' ? 'created_by'),'self status omits reporter and administrator identities');
 perform public.community_acknowledge_restriction(rid);
 perform pg_temp.assert_true(not public.community_access_allowed(),'own acknowledgment does not unblock');
 set local role service_role; perform set_config('request.jwt.claim.sub','',true);
 perform public.community_assert_access();
 perform pg_temp.assert_true(public.community_access_allowed(),'service role bypasses community restriction');
 set local role authenticated; perform set_config('request.jwt.claim.sub',target::text,true);
 perform pg_temp.error(format('select public.ops_community_unrestrict_user(%L,''self revoke'')',target),'42501');
 perform pg_temp.error(format('select public.ops_community_restriction_status(%L)',reporter),'42501');
 perform pg_temp.error('select * from public.community_access_restrictions','42501');
 perform pg_temp.error(format('update public.community_access_restrictions set revoked_at=now() where id=%L',rid),'42501');
 perform pg_temp.assert_true(public.community_access_status()->'active'->>'acknowledged_at' is not null,'own acknowledgment saved');
 perform pg_temp.error('select public.community_list_blocks()','42501');
 perform pg_temp.error(format('select public.community_message_history(%L)',reporter),'42501');
 perform pg_temp.error(format('select public.community_send_message(%L,''outgoing'',gen_random_uuid())',reporter),'42501');
 perform pg_temp.assert_true((select count(*)=0 from public.community_posts),'restricted feed reads hidden');
 perform pg_temp.assert_true((select count(*)=0 from public.community_posts where author_id=current_setting('test.third')::uuid),'restricted profile posts hidden');
 perform pg_temp.error('insert into public.community_posts(author_id,image_path) values(auth.uid(),auth.uid()||''/blocked.webp'')','42501');
 perform pg_temp.error(format('insert into public.community_comments(post_id,author_id,body) values(%L,auth.uid(),''blocked'')',post),'42501');
 perform pg_temp.error(format('insert into public.community_comments(post_id,author_id,body,parent_comment_id) values(%L,auth.uid(),''blocked'',%L)',post,parent),'23514');
 perform pg_temp.error(format('insert into public.community_likes(post_id,user_id) values(%L,auth.uid())',post),'42501');
 perform pg_temp.error('insert into storage.objects(bucket_id,name) values(''community-posts'',auth.uid()||''/blocked.webp'')','42501');
 perform pg_temp.assert_true((select count(*)=0 from storage.objects where bucket_id like 'community%'),'restricted storage reads hidden');
 perform public.save_account_preferences(0,'kg','{"sound":true}');
 perform public.save_athlete_plan(0,'weekly','{}','[]');
 perform public.save_athlete_body(0,'[]','[]');
 perform public.athlete_plan_library_page();
 perform public.student_program_overview();
 perform public.support_list_categories();
 support_id:=public.support_create_ticket('question','Restricted user support','Support remains available');
 perform pg_temp.assert_true(public.support_ticket_detail(support_id) is not null,'support remains available');
 workout:=public.start_workout_session(gen_random_uuid(),'{}');
 perform public.complete_workout_session((workout->>'id')::uuid,(workout->>'writer_token')::uuid,(workout->>'revision')::bigint,gen_random_uuid(),'{}');
 perform pg_temp.assert_true((select count(*)=1 from public.workout_sessions where user_id=target and status='completed'),'workout and history remain available');
 perform pg_temp.assert_true((public.load_athlete_body()->>'revision')::bigint>0,'body remains available');
 perform set_config('request.jwt.claim.sub',admin::text,true);
 perform public.ops_community_unrestrict_user(target,'review completed');
 r:=public.ops_community_restriction_status(target);
 perform pg_temp.assert_true(r->'active'='null'::jsonb,'revocation clears active restriction');
 perform set_config('request.jwt.claim.sub',target::text,true);
 perform pg_temp.assert_true(public.community_access_allowed(),'revocation restores access');
 perform public.community_send_message(reporter,'restored after revocation',gen_random_uuid());
 reset role;
 perform pg_temp.error(format('update public.community_access_restrictions set reason=''other'' where id=%L',rid),'42501');
 perform pg_temp.assert_true((select count(*)=5 from public.support_ticket_events where ticket_id=ticket and event_type='community_user_restricted'),'report retains restriction events');
 perform pg_temp.assert_true((select count(*)=5 from public.support_ticket_events where ticket_id=ticket and event_type='community_user_unrestricted'),'report retains replacement and revoke events');
 -- Expired historical rows are fixtures inserted directly; immutable history is never edited.
 insert into public.community_access_restrictions(user_id,restriction_type,reason,starts_at,ends_at) values(target,'temporary','spam',now()-interval '2 days',now()-interval '1 day');
 set local role authenticated; perform set_config('request.jwt.claim.sub',target::text,true);
 perform pg_temp.assert_true(public.community_access_allowed(),'expired restriction restores access');
 perform public.community_send_message(reporter,'restored',gen_random_uuid());
 insert into public.community_likes(post_id,user_id) values(post,target);
 set local role service_role; perform set_config('request.jwt.claim.sub','',true);
 perform public.community_assert_access();
 reset role;
 perform pg_temp.assert_true(not exists(select 1 from public.account_activity_guard_gaps()),'final schema has zero guard gaps: '||coalesce((select jsonb_agg(to_jsonb(g))::text from public.account_activity_guard_gaps() g),'[]'));
end$$;
rollback;
